import sys; sys.path.insert(0, __import__("pathlib").Path(__file__).resolve().parents[1].as_posix())
from explications import *

ENTREES = [
    ("## 🗝️ Vocabulaire", 'fin', apropos("Un ingénieur veut tester son circuit avant de le fabriquer. Peut-il le faire sans acheter un seul composant ?", "Oui, grâce à un **simulateur** comme **Tinkercad Circuits** : on construit et on teste le montage **à l'écran**, sans risque de griller un composant.\n\nMais attention : la simulation n'est pas la réalité. Dans cette séance, tu apprends à **dessiner un schéma normalisé**, à **simuler** dans Tinkercad, à **lire une datasheet** et à **dimensionner** un circuit, puis à comprendre les **limites** de la simulation.")),
    ("## 1.", 'fin', clair("Un schéma sert à **communiquer**. Plus le circuit est grand, plus il faut respecter les **conventions** : fils droits (horizontaux ou verticaux), **alimentation en haut**, **masse en bas**, **signal de gauche à droite**, **points** sur les jonctions, **noms et valeurs** sur chaque composant.\n\nTu rencontres aussi de **nouveaux symboles** : transistor, fusible, régulateur, relais, optocoupleur.") + "\n" + verifie(
        ("Où place-t-on l'alimentation et la masse sur un schéma ?", "L'**alimentation en haut**, la **masse en bas**."),
        ("À quoi sert le symbole du fusible ?", "À **protéger** le circuit : il **coupe** le courant en cas de surintensité."),
        ("Pourquoi note-t-on la valeur à côté de chaque composant ?", "Pour que le schéma soit **complet** : on peut monter ou dépanner le circuit sans autre document.")) + "\n" + retenir("Un bon schéma est **lisible** : fils droits, jonctions marquées, noms et valeurs.")),
    ("## 2.", 'fin', clair("Tinkercad Circuits est un **atelier virtuel**. Le travail se fait toujours en **quatre temps** :\n\n1. **Poser** les composants sur la zone de travail.\n2. **Les relier** avec des fils.\n3. **Régler** leurs valeurs (résistance, tension de l'alimentation).\n4. **Démarrer la simulation** (le triangle vert) et **observer**.\n\nTu peux aussi placer un **multimètre virtuel** pour mesurer : **en parallèle** pour la tension, **en série** pour le courant, comme dans la réalité.") + "\n" + verifie(
        ("Comment mesure-t-on la tension aux bornes d'une LED dans Tinkercad ?", "Avec le multimètre en **mode voltmètre**, branché **en parallèle** de la LED."),
        ("Que se passe-t-il si on oublie de démarrer la simulation ?", "Rien ne s'anime : il faut cliquer sur **« Démarrer la simulation »**."),
        ("Un composant simulé peut-il « griller » ?", "Oui, Tinkercad signale certaines erreurs (LED sans résistance), mais pas toutes les pannes de la vraie vie.")) + "\n" + retenir("Poser, relier, régler, simuler, observer.")),
    ("## 3.", 'fin', clair("Une datasheet est un **document technique** de plusieurs pages. Pas besoin de tout lire : on suit toujours **le même parcours** :\n\n1. la **première page** : à quoi sert le composant ;\n2. le tableau **« Absolute Maximum Ratings »** : les limites à **ne jamais dépasser** ;\n3. les **caractéristiques électriques** : les valeurs de **fonctionnement** ;\n4. le **brochage** : à quoi correspond chaque patte.") + "\n" + verifie(
        ("Que signifient les « Absolute Maximum Ratings » ?", "Les **valeurs limites absolues** : au-delà, le composant peut être **détruit**."),
        ("Pour un transistor BC547, que veut dire $I_C = 100\\,\\mathrm{mA}$ dans ce tableau ?", "Le **courant maximal** que peut supporter le collecteur : on reste **très en dessous** en fonctionnement normal."),
        ("Où trouve-t-on la correspondance entre les pattes et leur rôle ?", "Dans le **brochage** (« pinout »), souvent dessiné sur la première page.")) + "\n" + retenir("Limites absolues = à ne jamais dépasser ; valeurs typiques = pour calculer.")),
    ("## 4.", 'fin', clair("On veut allumer une LED (20 mA) depuis une sortie Arduino qui ne peut donner que **peu de courant**. On intercale un **transistor** qui joue le rôle d'**interrupteur commandé** : un **petit courant de base** pilote un **plus gros courant de collecteur**.\n\nDeux résistances, deux calculs :\n\n1. **$R_C$** (côté LED) protège la LED : $R_C = \\dfrac{V_{CC} - V_F - V_{CE_{sat}}}{I_F}$.\n2. **$R_B$** (côté base) limite le courant de base : on calcule d'abord $I_B = \\dfrac{I_C}{h_{FE}}$.\n\nPour que le transistor soit bien **saturé**, on choisit un $R_B$ **plus petit** que la valeur calculée (sécurité).") + "\n" + verifie(
        ("Pourquoi utilise-t-on un transistor entre l'Arduino et une charge puissante ?", "Parce qu'une sortie Arduino fournit **peu de courant** : le transistor permet de commander un **courant plus important**."),
        ("À quoi sert la résistance de base ?", "À **limiter le courant de base** pour ne pas endommager le transistor ni la sortie de l'Arduino."),
        ("Pourquoi prend-on le $h_{FE}$ **minimum** de la datasheet pour calculer ?", "Pour être sûr que le transistor est **bien saturé** même avec un composant moins performant.")) + "\n" + retenir("Le transistor commande un fort courant avec un petit.", "Deux résistances : $R_C$ protège la charge, $R_B$ limite le courant de base.")),
    ("## 5.", 'fin', clair("La simulation sert à **vérifier la logique** et à **pré-dimensionner**. Elle ne remplace pas la réalité : les composants simulés sont **idéaux** (une LED a exactement 2 V), alors que les vrais composants ont des **tolérances**, chauffent, et peuvent tomber en panne.") + "\n" + verifie(
        ("Cite une limite de la simulation.", "Les modèles sont **idéaux** : tolérances, chaleur, parasites et pannes réelles ne sont pas toutes reproduites."),
        ("À quoi sert alors la simulation ?", "À **valider la logique** et pré-dimensionner avant le montage réel.")) + "\n" + retenir("On simule pour préparer ; on mesure pour valider.")),
]
